{"implementation":"def solve(case):
    import math

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("missing required case field")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty array")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise ValueError("required_symbols must be an array of strings")

    by_id = {}
    roots = []
    required_node_fields = ("id", "parent", "symbol", "depth", "removable", "utility")

    for node in nodes:
        if not isinstance(node, dict):
            raise ValueError("each node must be an object")
        if any(field not in node for field in required_node_fields):
            raise ValueError("node is missing a required field")

        node_id = node["id"]
        parent = node["parent"]
        symbol = node["symbol"]
        depth = node["depth"]
        removable = node["removable"]
        utility = node["utility"]

        if not isinstance(node_id, str) or not node_id:
            raise ValueError("node id must be a non-empty string")
        if node_id in by_id:
            raise ValueError("node ids must be unique")
        if parent is not None and not isinstance(parent, str):
            raise ValueError("node parent must be a string or null")
        if not isinstance(symbol, str):
            raise ValueError("node symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise ValueError("node depth must be a non-negative integer")
        if not isinstance(removable, bool):
            raise ValueError("node removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise ValueError("node utility must be a finite number")

        by_id[node_id] = node
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("tree must have exactly one root")
    root_id = roots[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: [] for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is None:
            continue
        if parent not in by_id:
            raise ValueError("node parent does not exist")
        if parent == node_id:
            raise ValueError("node cannot be its own parent")
        if node["depth"] != by_id[parent]["depth"] + 1:
            raise ValueError("node depth is inconsistent with its parent")
        children[parent].append(node_id)

    visited = set()
    stack = [root_id]
    while stack:
        node_id = stack.pop()
        if node_id in visited:
            raise ValueError("node graph is cyclic")
        visited.add(node_id)
        stack.extend(children[node_id])
    if len(visited) != len(nodes):
        raise ValueError("nodes must form one connected tree")

    represented = {node["symbol"] for node in nodes}
    if any(symbol not in represented for symbol in required_symbols):
        raise ValueError("a required symbol is not represented")
    required = set(required_symbols)

    retained = set(by_id)
    removed = []
    candidates = sorted(by_id, key=lambda node_id: (-by_id[node_id]["depth"], node_id))

    for node_id in candidates:
        node = by_id[node_id]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue

        remaining_symbols = {
            by_id[retained_id]["symbol"]
            for retained_id in retained
            if retained_id != node_id
        }
        if not required.issubset(remaining_symbols):
            continue

        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
